#include <bits/stdc++.h>
using namespace std;

#define pb push_back
#define mp make_pair
#define all(x) (x).begin(), (x).end()
#define fi first
#define se second
#define SZ(x) ((int)(x).size())

typedef long long ll;
typedef double db;
typedef vector<int> VI;
typedef pair<int, int> PII;
typedef pair<long long, int> PLI;

mt19937 mrand(random_device{}());

const ll mod = 998244353;

ll powmod(ll a, ll b) {
    ll res = 1;
    a %= mod;
    assert(b >= 0);
    for (; b; b >>= 1) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
    }
    return res;
}

ll gcd(ll a, ll b) {
    return b ? gcd(b, a % b) : a;
}

#define Abs(x) ((x) > 0 ? (x) : -(x))

ll f[200006], ff[200006];

int n, k;

ll g(int k) {
    ll ret = 0;
    for (int i = k + 1; i <= n; i++) {
        ll tmp = f[n - i] * ff[i] % mod * f[n - i] % mod;
        ret = (ret + tmp) % mod;
    }
    return ret;
}

int main() {
    f[0] = f[1] = 1;

    scanf("%d%d", &n, &k);

    for (int i = 2; i <= n; i++)
        f[i] = f[i - 1] * i % mod;

    ff[0] = 1;
    for (int i = 1; i <= n; i++)
        ff[i] = ff[i - 1] * (n - i + 1) % mod * powmod(i, mod - 2) % mod;

    ll ans = 1;

    if (k >= n) {
        puts("0");
        return 0;
    }

    if (k == 0) {
        for (int i = 1; i <= n; i++)
            ans = ans * n % mod;
        printf("%lld\n", ans);
        return 0;
    }

    if (k == n - 1) {
        printf("%d\n", 2 * n);
        return 0;
    }

    printf("%lld\n", (g(k) - g(k - 1) + mod) % mod);
    return 0;
}

